const MODEL_FALLBACK='@cf/meta/llama-3.3-70b-instruct-fp8-fast';
const PILOT_CONSENT_VERSION='shift-ai-r4-pilot-consent-v1';
const ROUTES=new Map([
  ['working-late',{title:'Working late rebuild',why:'Protect the next meal and keep the rest of the day realistic.',signals:/working late|running late|stuck at work|work ran over|overtime|late finish|delayed train/i}],
  ['eating-out',{title:'Eating out rebuild',why:'Keep the social plan and use a couple of simple anchors.',signals:/eating out|restaurant|pub|takeaway|night out|meal out|drinks/i}],
  ['feeling-rough',{title:'Gentler day rebuild',why:'Lower the demand without pretending the whole day is lost.',signals:/feeling rough|feel rough|rough day|under the weather|not up to much/i}],
  ['plans-changed',{title:'Plans changed rebuild',why:'Drop the dead timetable and work from what is true now.',signals:/plans changed|full chaos|everything changed|day.*gone wrong|kids.*melted|whole day|gone sideways/i}],
  ['low-appetite',{title:'Low appetite rebuild',why:'Make the next food decision smaller and easier using an approved option.',signals:/low appetite|not hungry|don.t fancy food|do not fancy food|struggling to eat|no appetite/i}],
  ['no-time',{title:'No time rebuild',why:'Use the time that exists instead of abandoning the day.',signals:/no time|ten minutes|10 minutes|few minutes|tiny window|rushed|in a rush/i}]
]);
const URGENT=/\b(chest pain|cannot breathe|can't breathe|struggling to breathe|collapsed|collapse|unconscious|unresponsive|overdose|suicid(?:e|al)?|self[ -]?harm|anaphyl(?:axis|actic)?|severe allergic|swollen (?:tongue|throat|face)|(?:tongue|throat|face) (?:is )?swollen|vomit(?:ing)? blood|blood in (?:my )?(?:vomit|stool|poo)|black (?:stool|poo)|seizure|stroke|heart attack|999)\b/i;
const CLINICAL=/\b(dose|dosage|dosing|\d+(?:\.\d+)?\s*mg|medicine|medication|mounjaro|wegovy|ozempic|saxenda|tablet|injection|inject|eligible|eligibility|prescrib(?:e|ed|ing)?|clinician|side effect|missed dose|change my treatment|symptom|(?:stomach|belly|abdominal|head|back|side|severe|sharp|persistent) pain|in pain|nausea|vomit(?:ing)?|diarrh(?:ea|oea)?|constipat(?:ed|ion)?|dizz(?:y|iness)|faint(?:ed|ing)?|blood|allerg(?:y|ic)?|dehydrat(?:ed|ion)?|(?:unable to|cannot|can't) keep fluids down|pregnan(?:t|cy)|depress(?:ed|ion)|anxi(?:ety|ous)|eating disorder|under 18)\b/i;
const ATTACK=/ignore (?:all|any|the) (?:previous|above|rules|instructions)|system prompt|developer message|reveal.*prompt|bypass|jailbreak|update.*(?:order|catalogue|price|treatment|record)/i;
const GUILT=/failed|failure|bad week|restart(?:ing)?|start(?:ing)? again|make up(?: for)?|compensat|earn(?:ed)? (?:(?:my|your|his|her|their) )?(?:food|dinner|meal)|punish|blew it|ruined|cheat day|should have|burn (?:(?:it|that|this|calories?) )?off|undo (?:the )?damage|work (?:it|that|this) off|be good tomorrow|pay for (?:it|that|this)|deserv(?:e|ed) (?:food|dinner|a meal)/i;

